const response = $input.first().json;

const results = response.results || [];

const articles = results
  .filter(article => article.content && article.url)
  .map((article, index) => ({
    sourceNumber: index + 1,
    title: article.title,
    url: article.url,
    relevanceScore: article.score,
    content: article.content.slice(0, 3000)
  }));

return [
  {
    json: {
      searchQuery: response.query,
      totalSources: articles.length,
      researchSources: articles
    }
  }
];

const data = $input.first().json;

const sources = data.researchSources || [];

const sourceText = sources.map(source => {
  return `
SOURCE ${source.sourceNumber}
Title: ${source.title}
URL: ${source.url}
Relevance: ${source.relevanceScore}

Content:
${source.content}
`;
}).join("\n\n");

const prompt = `
You are a professional research analyst.

Research topic: ${data.searchQuery}

Your task is to produce a well-structured research report
using the supplied research sources.

Instructions:

1. Write a concise executive summary.
2. Explain the major findings.
3. Identify important trends and developments.
4. Discuss opportunities and challenges.
5. Provide a conclusion.
6. Cite sources using [1], [2], etc.
7. Include a source list with the original URLs.
8. Never invent facts, statistics or citations.
9. Clearly distinguish sourced information from your own analysis.
10. If the available evidence is insufficient, say so.

Use Markdown formatting with clear headings.

RESEARCH SOURCES:
${sourceText}
`;

return [{
  json: {
    researchTopic: data.searchQuery,
    totalSources: sources.length,
    geminiPrompt: prompt
  }
}];

