const response = $input.first().json;

const candidate = response.candidates?.[0];

if (!candidate) {
  throw new Error("Gemini returned no response candidate.");
}

// Extract generated report
const report = (candidate.content?.parts || [])
  .map(part => part.text || "")
  .join("\n")
  .trim();

if (!report) {
  throw new Error("Gemini returned an empty research report.");
}

// Escape HTML for safe email rendering
const safeReport = report.replace(/[&<>"']/g, char => ({
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;"
}[char]));

// Convert Markdown-style headings and basic formatting
const formattedReport = safeReport
  .replace(/^### (.*)$/gm, '<h3>$1</h3>')
  .replace(/^## (.*)$/gm, '<h2>$1</h2>')
  .replace(/^# (.*)$/gm, '<h1>$1</h1>')
  .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
  .replace(/\n/g, '<br>');

const reportHtml = `
<div style="max-width:900px;margin:auto;padding:24px;font-family:Arial,sans-serif;color:#333;line-height:1.7;">
  <h1 style="color:#604080;">AI Research Report</h1>
  ${formattedReport}
  <hr>
  <p style="color:#888;font-size:12px;">
    Generated automatically using n8n, Tavily and Google Gemini.
  </p>
</div>
`;

// Retrieve original research topic
const researchData = $("Build Gemini Prompt").first().json;

return [
  {
    json: {
      researchTopic: researchData.researchTopic,
      totalSources: researchData.totalSources,
      report: report,
      reportHtml: reportHtml,
      reportLength: report.length,
      status: "completed",
      generatedAt: new Date().toISOString()
    }
  }
];
